#include <bits/stdc++.h>
using namespace std;

vector<long long> pf[200001];
long long dp[200001];
bool cmp[200001];

void pre() {
    for (long long i = 2; i <= 200000; i++) {
        if (!cmp[i]) {
            cmp[i]=true;
            for (long long j = 2*i; j <= 200000; j+=i) {
                pf[j].push_back(i);
                cmp[j]=true;
            }
            pf[i].push_back(i);
        }
    }
}

void solve() {
    long long N, K; cin >> N >> K;
    long long aa = 0;
    vector<long long> dp(N+1,1e18);
    for (long long i = 1; i <= N; i++) {
        if (i<=K) {dp[i]=0;}
        for (auto x : pf[i]) {dp[i]=min(dp[i],dp[i/x]*x+1);}
    }
    for (long long i = 0; i < N; i++) {
        long long a; cin >> a;
        aa+=dp[a];
    }
    cout << aa << endl;
}

int main() {
    pre();
    long long T; cin >> T;
    while (T--) {solve();}
}

#include <bits/stdc++.h>
using namespace std;

bool check(long long mid, vector<pair<long long, long long>> &A) {
    long long n = 1;
    long long ex = 0;
    long long p = mid;
    for (long long i = 0; i < A.size(); i++) {
        if (p-A[i].first+(63-__builtin_clzll(n))>60) {return false;}
        n<<=(p-A[i].first-1);
        if (!A[i].first) {ex+=A[i].second; break;}
        if (A[i].second>n) {ex+=A[i].second-n;}
        else {n=(n<<1)-A[i].second;}
        p=A[i].first;
    }
    return (ex>=n);
}

void solve() {
    long long N; cin >> N;
    vector<pair<long long, long long>> A;
    long long lo = 0;
    long long hi = 1000000100;
    for (long long i = 0; i < N; i++) {
        long long a, b; cin >> a >> b;
        A.push_back({a,b});
        lo=max(lo,a);
    }
    sort(A.rbegin(),A.rend());
    if (A.back().first) {A.push_back({0,0});}
    while (lo<hi) {
        long long mid = (lo+hi+1)/2;
        if (check(mid,A)) {lo=mid;}
        else {hi=mid-1;}
    }
    cout << lo << endl;
}

int main() {
    long long T; cin >> T;
    while (T--) {solve();}
}

#include <bits/stdc++.h>
using namespace std;

void dfs(long long node, long long par, vector<long long> &A, vector<long long> &B, vector<long long> &g, vector<vector<long long>> &adj) {
    long long gc = 0;
    long long tt = 0;
    for (auto x : adj[node]) {
        if (x != par) {
            dfs(x,node,A,B,g,adj);
            if (g[x]!=B[x]) {gc=gcd(gc,g[x]);}
            tt+=A[x];
        }
    }
    gc=gcd(gc,tt);
    gc=gcd(gc,B[node]);
    g[node]=gc;
}

void solve() {
    long long N; cin >> N;
    vector<long long> A; A.push_back(-1);
    vector<long long> B; B.push_back(-1);
    vector<vector<long long>> adj(N+1);
    for (long long i = 0; i < N; i++) {
        long long a; cin >> a;
        A.push_back(a);
    }
    for (long long i = 0; i < N; i++) {
        long long a; cin >> a;
        B.push_back(a);
    }
    for (long long i = 0; i < N-1; i++) {
        long long a, b; cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    vector<long long> g(N+1); //init to 0 for identity gcd
    dfs(1,0,A,B,g,adj);
    long long aa = 0;
    for (long long i = 1; i <= N; i++) {aa+=((B[i]-A[i]-1)/g[i])*g[i]+A[i];}
    cout << aa << endl;
}

int main() {
    long long T; cin >> T;
    while (T--) {solve();}
}

#include <bits/stdc++.h>
using namespace std;

struct lst { //cur range add range max, change accordingly, no need for l,r in range add range mx
    vector<int> seg;
    vector<bool> tg;
    vector<int> lz;
    int sz = 1;
    int id = 0; //change sent
    int acc(int x, int y) {return max(x,y);} //other more complex lst can do range set and range add
    void pull(int n) {seg[n]=acc(seg[n<<1],seg[(n<<1)|1]);}
    void apply(int n, int l, int r, int v) {seg[n]=v; tg[n]=true; lz[n]=v;} //if something else, change id, acc, apply, and how lz accumulates/replaces in push
    void push(int n, int l, int r) {if (!tg[n]) {return;} tg[n]=false; apply(n<<1,l,(l+r)/2,lz[n]); apply((n<<1)|1,(l+r)/2+1,r,lz[n]); lz[n]=0;}
    lst(vector<int> A) { //inp 0 index
        while (sz<A.size()) {sz<<=1;}
        seg.assign(2*sz,id);
        tg.assign(2*sz,false); //in case 0 is a range set
        lz.assign(2*sz,0);
        for (int i = 0; i < A.size(); i++) {seg[sz+i]=A[i];}
        for (int i = sz-1; i >= 1; i--) {pull(i);}
    }
    int qq(int n, int l, int r, int sl, int sr) {
        if (sl>r||sr<l) {return id;}
        if (l<=sl&&sr<=r) {return seg[n];}
        push(n,sl,sr);
        return acc(qq(n<<1,l,r,sl,(sl+sr)/2),qq((n<<1)|1,l,r,(sl+sr)/2+1,sr));
    }
    void uu(int n, int l, int r, int sl, int sr, int v) {
        if (sl>r||sr<l) {return;}
        if (l<=sl&&sr<=r) {apply(n,sl,sr,v); return;}
        push(n,sl,sr);
        uu(n<<1,l,r,sl,(sl+sr)/2,v);
        uu((n<<1)|1,l,r,(sl+sr)/2+1,sr,v);
        pull(n);
    }
    int q(int l, int r) {return qq(1,l,r,1,sz);}
    void u(int l, int r, int v) {uu(1,l,r,1,sz,v);}
};


void solve() {
    int N, M; cin >> N >> M;
    vector<int> A;
    for (int i = 0; i < N; i++) {
        A.push_back(i+1);
    }
    vector<vector<int>> tt(N+1);
    vector<int> ndp1(M+1);
    for (int i = 1; i <= M; i++) {
        int a; cin >> a;
        tt[a].push_back(i);
    }
    for (int i = 1; i <= N; i++) {
        if (tt[i].empty()) {cout << -1 << endl; return;}
    }
    vector<int> ii(M+1); // one sentinel at end so no RE
    lst dp1(ii);
    bool f = true;
    for (auto x : A) {
        for (auto t : tt[x]) {
            int rr = dp1.q(t+1,M+1);
            ndp1[t]=(rr?rr+1:rr+(f));
        }
        for (auto t : tt[x]) {
            dp1.u(t,t,ndp1[t]);
        }
        dp1.u(tt[x].back()+1,M+1,0);
        if (f) {f=false;}
    }
    vector<int> ndp2(M+1);
    reverse(A.begin(),A.end());
    lst dp2(ii);
    f=true;
    for (auto x : A) {
        for (auto t : tt[x]) {
            int rr = dp2.q(t+1,M+1);
            ndp2[t]=(rr?rr+1:rr+(f));
        }
        for (auto t : tt[x]) {
            dp2.u(t,t,ndp2[t]);
        }
        dp2.u(tt[x].back()+1,M+1,0);
        if (f) {f=false;}
    }
    int aa = 0;
    for (int i = 1; i <= M; i++) {aa=max(aa,dp1.q(i,i)+dp2.q(i,i)-1);}
    cout << N-aa << endl;
}

int main() {
    int T; cin >> T;
    while (T--) {solve();}
}

#include <bits/stdc++.h>
using namespace std;

struct tri { //inp zero index vector, transformed to 1 index
    vector<int> s;
    int sz = 1;
    tri(vector<int> &A) {
        while (sz<A.size()) {sz<<=1;}
        s.assign(2*sz,0);
        for (int i = 0; i < A.size(); i++) {s[i+sz] = A[i];}
        for (int i = sz-1; i >= 1; i--) {s[i]=max(s[i<<1],s[(i<<1)|1]);}
    }
    void u(int i, int x) {
        int p = sz+i-1; s[p] = x;
        for (p>>=1; p; p>>=1) {s[p]=max(s[p<<1],s[(p<<1)|1]);}
    }
    int aa(int n, int l, int r, int sl, int sr) {
        if (l<=sl&&sr<=r) {return s[n];}
        else if (sr<l||sl>r) {return 0;}
        else {return max(aa(n<<1,l,r,sl,(sl+sr)>>1),aa((n<<1)|1,l,r,((sl+sr)>>1)+1,sr));}
    }
    int q(int l, int r) {return aa(1,l,r,1,sz);}
};

void solve() {
    int N, M; cin >> N >> M;
    vector<int> A;
    for (int i = 0; i < N; i++) {
        A.push_back(i+1);
    }
    vector<vector<int>> tt(N+1);
    vector<int> ndp1(M+1);
    for (int i = 1; i <= M; i++) {
        int a; cin >> a;
        tt[a].push_back(i);
    }
    for (int i = 1; i <= N; i++) {
        if (tt[i].empty()) {cout << -1 << endl; return;}
    }
    vector<int> ii(M+1); // one sentinel at end so no RE
    tri dp1(ii);
    set<int> act;
    bool f = true;
    for (auto x : A) {
        for (auto t : tt[x]) {
            int rr = dp1.q(t+1,M+1);
            ndp1[t]=(rr?rr+1:rr+(f));
        }
        for (auto t : tt[x]) {
            dp1.u(t,ndp1[t]);
            act.insert(t);
        }
        while (!act.empty()&&(*act.rbegin()>tt[x].back())) {dp1.u((*act.rbegin()),0); act.erase(*act.rbegin());}
        if (f) {f=false;}
    }
    vector<int> ndp2(M+1);
    act.clear();
    reverse(A.begin(),A.end());
    tri dp2(ii);
    f=true;
    for (auto x : A) {
        for (auto t : tt[x]) {
            int rr = dp2.q(t+1,M+1);
            ndp2[t]=(rr?rr+1:rr+(f));
        }
        for (auto t : tt[x]) {
            dp2.u(t,ndp2[t]);
            act.insert(t);
        }
        while (!act.empty()&&(*act.rbegin()>tt[x].back())) {dp2.u((*act.rbegin()),0); act.erase(*act.rbegin());}
        if (f) {f=false;}
    }
    int aa = 0;
    for (int i = 1; i <= M; i++) {aa=max(aa,dp1.q(i,i)+dp2.q(i,i)-1);}
    cout << N-aa << endl;
}

int main() {
    int T; cin >> T;
    while (T--) {solve();}
}
